mapper.select:
SELECT * FROM epd_calendar
WHERE calendar_id = #{calendarId}
  AND YEAR(calendar_date) = #{year}
  AND MONTH(calendar_date) = #{month}
ORDER BY calendar_date

mapper.delete:
DELETE FROM epd_calendar 
WHERE calendar_id = #{calendarId}
  AND inv_org = #{invOrg}
  AND calendar_date BETWEEN #{startDate} AND #{endDate}
